const cityDialogue=Object.freeze({"city-klaus-dieter-klein":{"voiceId":"stadt-klaus-dieter-klein","germany":[{"id":"stadt-klaus-dieter-klein-01","text":"Ich würde erst das richtige Formular nehmen. Mit dem falschen können Sie sehr ordentlich in die falsche Richtung arbeiten.","english":"I would start with the right form. With the wrong one, you can work very neatly in the wrong direction."},{"id":"stadt-klaus-dieter-klein-02","text":"Wenn das Feld zu klein ist, schreiben Sie kleiner. Der Vorgang wird davon nicht kleiner, aber er passt besser in den Ordner.","english":"If the box is too small, write smaller. That does not make the case smaller, but it fits in the folder better."}],"berlin":[{"id":"stadt-klaus-dieter-klein-03","text":"Ich würde erst das richtige Formular nehmen. With the wrong one können Sie sehr ordentlich in the wrong direction arbeiten.","english":"I would start with the right form. With the wrong one, you can work very neatly in the wrong direction."},{"id":"stadt-klaus-dieter-klein-04","text":"If das Feld is too small, schreiben Sie kleiner. The case wird davon nicht kleiner, aber er passt better in den Ordner.","english":"If the box is too small, write smaller. That does not make the case smaller, but it fits in the folder better."}]},"city-brigitte-mueller":{"voiceId":"stadt-brigitte-mueller","germany":[{"id":"stadt-brigitte-mueller-01","text":"Bevor Sie um den Bauzaun gehen, klären Sie bitte, auf welcher Seite Ihr Anliegen liegt. Sonst erklären Sie es am falschen Zaun.","english":"Before going around the construction fence, please establish which side your concern belongs on. Otherwise you will explain it at the wrong fence."},{"id":"stadt-brigitte-mueller-02","text":"Die Baustelle ist nicht fertig. Die Liste, warum sie nicht fertig ist, können wir aber schon abheften.","english":"The construction is not finished. But we can already file the list of reasons why it is not finished."}],"berlin":[{"id":"stadt-brigitte-mueller-03","text":"Before Sie um den Bauzaun gehen, klären Sie bitte, on which side Ihr Anliegen liegt. Otherwise erklären Sie es am falschen Zaun.","english":"Before going around the construction fence, please establish which side your concern belongs on. Otherwise you will explain it at the wrong fence."},{"id":"stadt-brigitte-mueller-04","text":"Die Baustelle is not finished. Die Liste, why sie nicht fertig ist, können wir aber schon file away.","english":"The construction is not finished. But we can already file the list of reasons why it is not finished."}]},"city-wolfgang-schulz":{"voiceId":"stadt-wolfgang-schulz","germany":[{"id":"stadt-wolfgang-schulz-01","text":"Ich komme immer eine Viertelstunde zu früh. Dann bin ich pünktlich, wenn mir einfällt, was ich vergessen habe.","english":"I always arrive fifteen minutes early. Then I am on time when I remember what I have forgotten."},{"id":"stadt-wolfgang-schulz-02","text":"Spontan geht bei mir nur mit Termin. Sonst weiß ich vorher gar nicht, wie lange ich offen für Überraschungen sein soll.","english":"I can only be spontaneous by appointment. Otherwise I have no way of knowing in advance how long to be open to surprises."}],"berlin":[{"id":"stadt-wolfgang-schulz-03","text":"Ich komme always eine Viertelstunde too early. Dann bin ich on time, wenn mir einfällt, was ich vergessen habe.","english":"I always arrive fifteen minutes early. Then I am on time when I remember what I have forgotten."},{"id":"stadt-wolfgang-schulz-04","text":"Spontaneous geht bei mir nur mit Termin. Otherwise weiß ich vorher gar nicht, how long ich open für Überraschungen sein soll.","english":"I can only be spontaneous by appointment. Otherwise I have no way of knowing in advance how long to be open to surprises."}]},"city-ursula-neumann":{"voiceId":"stadt-ursula-neumann","germany":[{"id":"stadt-ursula-neumann-01","text":"Sie stehen genau da, wo ich vorbeigehen wollte. Nein, noch wollte ich nicht vorbeigehen. Ich möchte mir das aber freihalten.","english":"You are standing exactly where I wanted to pass. No, I did not want to pass yet. But I want to keep that option clear."},{"id":"stadt-ursula-neumann-02","text":"Ein Schritt zur Seite wäre freundlich. Dort hatte ich allerdings für den Rückweg Platz gelassen.","english":"It would be kind of you to step aside. Though I had left that space for the return journey."}],"berlin":[{"id":"stadt-ursula-neumann-03","text":"Sie stehen exactly da, wo ich vorbeigehen wollte. No, noch wollte ich nicht vorbei. Ich möchte keep that option clear.","english":"You are standing exactly where I wanted to pass. No, I did not want to pass yet. But I want to keep that option clear."},{"id":"stadt-ursula-neumann-04","text":"One step zur Seite wäre friendly. Dort hatte ich allerdings space für den Rückweg gelassen.","english":"It would be kind of you to step aside. Though I had left that space for the return journey."}]},"city-manfred-din":{"voiceId":"stadt-manfred-din","germany":[{"id":"stadt-manfred-din-01","text":"Die Pflasterfuge ist nicht schief. Sie führt nur einen anderen Winkelstandard. Wir sollten uns trotzdem erst auf einen einigen.","english":"The paving joint is not crooked. It merely follows a different angular standard. We should still agree on one first."},{"id":"stadt-manfred-din-02","text":"Stellen Sie sich bitte parallel zur Bordsteinkante. Dann erkennt man wenigstens, ob Sie ungeordnet warten oder ordentlich im Weg stehen.","english":"Please stand parallel to the curb. Then at least we can tell whether you are waiting in disorder or obstructing the way in an orderly fashion."}],"berlin":[{"id":"stadt-manfred-din-03","text":"Die Pflasterfuge is not crooked. Sie führt nur einen different Winkelstandard. We should trotzdem erst agree on one.","english":"The paving joint is not crooked. It merely follows a different angular standard. We should still agree on one first."},{"id":"stadt-manfred-din-04","text":"Please stellen Sie sich parallel zur Bordsteinkante. Dann erkennt man wenigstens, whether Sie ungeordnet warten or properly im Weg stehen.","english":"Please stand parallel to the curb. Then at least we can tell whether you are waiting in disorder or obstructing the way in an orderly fashion."}]},"city-irmgard-aktenstapel":{"voiceId":"stadt-irmgard-aktenstapel","germany":[{"id":"stadt-irmgard-aktenstapel-01","text":"Den Bauzaun kannte ich schon, als das Formular noch grün war. Jetzt ist beides grau. So hält man die Unterlagen aktuell.","english":"I knew that construction fence when the form was still green. Now both are grey. That is how you keep the paperwork up to date."},{"id":"stadt-irmgard-aktenstapel-02","text":"Werfen Sie die alte Bescheinigung nicht weg. Wenn die neue wieder ausläuft, braucht man etwas, mit dem man den Stapel gerade hält.","english":"Do not throw away the old certificate. When the new one expires again, you need something to keep the stack level."}],"berlin":[{"id":"stadt-irmgard-aktenstapel-03","text":"Den Bauzaun kannte ich schon, als das Formular noch green war. Now ist beides grey. So hält man die Unterlagen up to date.","english":"I knew that construction fence when the form was still green. Now both are grey. That is how you keep the paperwork up to date."},{"id":"stadt-irmgard-aktenstapel-04","text":"Do not werfen Sie die alte Bescheinigung weg. Wenn die neue wieder expires, braucht man etwas, to keep den Stapel straight.","english":"Do not throw away the old certificate. When the new one expires again, you need something to keep the stack level."}]},"city-guenther-tuev":{"voiceId":"stadt-guenther-tuev","germany":[{"id":"stadt-guenther-tuev-01","text":"Halt! Mit dem Schuh schon auf der Kante und dem Plan noch auf dem Gehweg. Erst für eine ordentliche Laufrichtung entscheiden!","english":"Stop! Your shoe is already on the curb while your plan is still on the sidewalk. Decide on a proper direction of travel first!"},{"id":"stadt-guenther-tuev-02","text":"Nicht einfach loslaufen! Ich habe Ihren ersten Schritt noch gar nicht zu Ende geprüft.","english":"Do not just start walking! I have not even finished inspecting your first step."}],"berlin":[{"id":"stadt-guenther-tuev-03","text":"Stop! Mit dem Schuh schon auf der Kante und the plan noch auf dem Gehweg. First decide on eine proper Laufrichtung!","english":"Stop! Your shoe is already on the curb while your plan is still on the sidewalk. Decide on a proper direction of travel first!"},{"id":"stadt-guenther-tuev-04","text":"Do not einfach loslaufen! Ich habe Ihren first step noch gar nicht fertig inspected.","english":"Do not just start walking! I have not even finished inspecting your first step."}]},"city-hannelore-sparkasse":{"voiceId":"stadt-hannelore-sparkasse","germany":[{"id":"stadt-hannelore-sparkasse-01","text":"Für den Umweg bekomme ich keine Zinsen. Gehen Sie bitte zur Seite, bevor hier noch mehr Zeit unverzinst herumliegt.","english":"I earn no interest on the detour. Please step aside before even more time sits here earning nothing."},{"id":"stadt-hannelore-sparkasse-02","text":"Sie können gern hier warten. Rechnen Sie nur Ihre Wartefläche nicht zu meinem Durchgang dazu.","english":"You are welcome to wait here. Just do not count your waiting area as part of my passageway."}],"berlin":[{"id":"stadt-hannelore-sparkasse-03","text":"Für den Umweg bekomme ich no interest. Please gehen Sie zur Seite, before hier noch mehr Zeit unverzinst herumliegt.","english":"I earn no interest on the detour. Please step aside before even more time sits here earning nothing."},{"id":"stadt-hannelore-sparkasse-04","text":"Sie können gern hier wait. Just rechnen Sie Ihre Wartefläche nicht into meinen Durchgang.","english":"You are welcome to wait here. Just do not count your waiting area as part of my passageway."}]},"city-karl-heinz-post":{"voiceId":"stadt-karl-heinz-post","germany":[{"id":"stadt-karl-heinz-post-01","text":"Der Briefkasten ist zuständig, solange der Brief nicht drin ist. Danach müssen Sie warten, bis jemand anders zuständig ist.","english":"The mailbox is responsible as long as the letter is not inside it. After that, you must wait until someone else is responsible."},{"id":"stadt-karl-heinz-post-02","text":"Eine Zustellung bedeutet, dass ich etwas abgegeben habe. Dass Sie es auch bekommen haben, müssten Sie bitte mit der Zustellung klären.","english":"A delivery means that I handed something over. Whether you also received it is something you would have to clarify with the delivery."}],"berlin":[{"id":"stadt-karl-heinz-post-03","text":"Der Briefkasten is responsible, solange der Brief nicht drin ist. After that müssen Sie warten, until jemand anders responsible ist.","english":"The mailbox is responsible as long as the letter is not inside it. After that, you must wait until someone else is responsible."},{"id":"stadt-karl-heinz-post-04","text":"Eine delivery bedeutet, dass ich etwas abgegeben habe. Whether Sie es auch bekommen haben, müssten Sie bitte mit der delivery klären.","english":"A delivery means that I handed something over. Whether you also received it is something you would have to clarify with the delivery."}]},"city-herbert-rasenaufsicht":{"voiceId":"stadt-herbert-rasenaufsicht","germany":[{"id":"stadt-herbert-rasenaufsicht-01","text":"Runter vom Grün! Das Gras soll sich hier ordentlich ausbreiten, aber doch nicht unter Leuten.","english":"Get off the grass! The grass is supposed to spread properly here, but not underneath people."},{"id":"stadt-herbert-rasenaufsicht-02","text":"Gehen Sie auf den Weg! Und nehmen Sie den Fuß vom Wegrand. Ich trenne hier gerade Grünfläche und Gehabsicht.","english":"Go onto the path! And take your foot off its edge. I am separating green space from the intention to walk."}],"berlin":[{"id":"stadt-herbert-rasenaufsicht-03","text":"Get off dem Grün! Das Gras soll sich hier properly ausbreiten, aber doch nicht under people.","english":"Get off the grass! The grass is supposed to spread properly here, but not underneath people."},{"id":"stadt-herbert-rasenaufsicht-04","text":"Go auf den Weg! Und nehmen Sie den Fuß vom Wegrand. Ich trenne hier gerade green space und walking intention.","english":"Go onto the path! And take your foot off its edge. I am separating green space from the intention to walk."}]},"city-waltraud-ordnung":{"voiceId":"stadt-waltraud-ordnung","germany":[{"id":"stadt-waltraud-ordnung-01","text":"Jetzt bleiben Sie doch nicht mitten im Durchgang stehen! Und bitte auch nicht einfach weitergehen, während ich Ihnen etwas sage!","english":"Do not stand right in the passageway! And please do not just walk away while I am telling you something either!"},{"id":"stadt-waltraud-ordnung-02","text":"Wenn jeder hier so einen halben Schritt macht, steht nachher die ganze Straße versetzt. Das kann ich nicht für alle wieder gerade erklären!","english":"If everyone takes a half step like that, the entire street will end up out of alignment. I cannot explain it straight again for everyone!"}],"berlin":[{"id":"stadt-waltraud-ordnung-03","text":"Do not jetzt mitten im Durchgang stehen bleiben! And bitte auch nicht einfach walk away, während ich Ihnen etwas sage!","english":"Do not stand right in the passageway! And please do not just walk away while I am telling you something either!"},{"id":"stadt-waltraud-ordnung-04","text":"If jeder hier so einen half step macht, steht nachher die ganze Straße out of alignment. Ich kann das nicht für alle straight erklären!","english":"If everyone takes a half step like that, the entire street will end up out of alignment. I cannot explain it straight again for everyone!"}]},"city-erwin-archiv":{"voiceId":"stadt-erwin-archiv","germany":[{"id":"stadt-erwin-archiv-01","text":"Die Baustelle ist im Archiv schon abgeschlossen. Draußen braucht sie offenbar noch eine Durchschrift davon.","english":"The construction is already closed in the archive. Apparently it still needs a duplicate of that outside."},{"id":"stadt-erwin-archiv-02","text":"Stellen Sie Ihre Frage hinten an den Stapel. Die unterste wartet seit Jahren, die kennt den Ablauf.","english":"Put your question at the back of the stack. The bottom one has been waiting for years; it knows the procedure."}],"berlin":[{"id":"stadt-erwin-archiv-03","text":"Die Baustelle is already closed im Archiv. Outside braucht sie apparently noch eine Durchschrift davon.","english":"The construction is already closed in the archive. Apparently it still needs a duplicate of that outside."},{"id":"stadt-erwin-archiv-04","text":"Put Ihre Frage hinten an den Stapel. The bottom one wartet seit Jahren, die knows the procedure.","english":"Put your question at the back of the stack. The bottom one has been waiting for years; it knows the procedure."}]},"city-renate-termin":{"voiceId":"stadt-renate-termin","germany":[{"id":"stadt-renate-termin-01","text":"Ohne Termin brauchen Sie hier nicht so lange zu überlegen! Für spontanes Nachfragen ist der spontane Zeitraum längst vergeben.","english":"Without an appointment, you need not take so long to think here! The spontaneous time slot for spontaneous questions has long since been booked."},{"id":"stadt-renate-termin-02","text":"Sie hatten nur eine kurze Frage? Dann hätten Sie bitte auch nur kurz zu spät kommen dürfen!","english":"You only had a short question? Then you should only have been briefly late!"}],"berlin":[{"id":"stadt-renate-termin-03","text":"Without Termin brauchen Sie hier nicht so lange zu überlegen! For spontaneous Nachfragen ist der spontaneous Zeitraum längst booked.","english":"Without an appointment, you need not take so long to think here! The spontaneous time slot for spontaneous questions has long since been booked."},{"id":"stadt-renate-termin-04","text":"You had nur eine short question? Dann hätten Sie bitte auch nur briefly zu spät kommen dürfen!","english":"You only had a short question? Then you should only have been briefly late!"}]},"city-heinz-mietnachweis":{"voiceId":"stadt-heinz-mietnachweis","germany":[{"id":"stadt-heinz-mietnachweis-01","text":"Ein Mietnachweis beweist vor allem, dass Sie mit einem Nachweis angekommen sind. Nach der Miete fragt dann wieder ein anderer.","english":"A rental certificate mainly proves that you arrived with a certificate. Someone else will ask about the rent."},{"id":"stadt-heinz-mietnachweis-02","text":"Früher brauchten Sie nur die alte Bescheinigung. Jetzt brauchen Sie die alte, um zu beweisen, dass die neue überhaupt neu ist.","english":"Previously, you only needed the old certificate. Now you need the old one to prove that the new one really is new."}],"berlin":[{"id":"stadt-heinz-mietnachweis-03","text":"Ein Mietnachweis mainly proves, dass Sie mit einem Nachweis angekommen sind. About the rent fragt dann wieder somebody else.","english":"A rental certificate mainly proves that you arrived with a certificate. Someone else will ask about the rent."},{"id":"stadt-heinz-mietnachweis-04","text":"Before brauchten Sie nur die alte Bescheinigung. Now brauchen Sie die alte, to prove dass die neue überhaupt new ist.","english":"Previously, you only needed the old certificate. Now you need the old one to prove that the new one really is new."}]},"city-monika-zebra":{"voiceId":"stadt-monika-zebra","germany":[{"id":"stadt-monika-zebra-01","text":"Ich warte hier lieber, bis alle fertig sind mit ihrem Vorrang. Danach kann ich in Ruhe rüber.","english":"I would rather wait here until everyone is finished with their priority. Then I can cross in peace."},{"id":"stadt-monika-zebra-02","text":"Auf dem Zebrastreifen haben wir alle Platz. Bloß nicht gleichzeitig an derselben Stelle. Das könnte man sich doch vorher kurz aufteilen.","english":"There is room for all of us on the crossing. Just not in the same spot at the same time. Surely we could briefly allocate that beforehand."}],"berlin":[{"id":"stadt-monika-zebra-03","text":"Ich warte hier lieber, until alle fertig sind mit their priority. After that kann ich in Ruhe rüber.","english":"I would rather wait here until everyone is finished with their priority. Then I can cross in peace."},{"id":"stadt-monika-zebra-04","text":"On dem Zebrastreifen haben wir alle space. Just nicht gleichzeitig an derselben Stelle. We could doch vorher kurz allocate that.","english":"There is room for all of us on the crossing. Just not in the same spot at the same time. Surely we could briefly allocate that beforehand."}]},"city-joachim-fundsache":{"voiceId":"stadt-joachim-fundsache","germany":[{"id":"stadt-joachim-fundsache-01","text":"Das ist nicht mein verlorener Gegenstand. Wenn Sie den Besitzer suchen, verlieren Sie bitte nicht auch noch meine Zeit.","english":"That is not my lost object. If you are looking for its owner, please do not lose my time as well."},{"id":"stadt-joachim-fundsache-02","text":"Die Zuständigkeit liegt hier irgendwo. Falls Sie sie finden, geben Sie sie bitte nicht bei mir ab.","english":"The responsibility is lying around here somewhere. If you find it, please do not hand it in to me."}],"berlin":[{"id":"stadt-joachim-fundsache-03","text":"That is nicht mein lost Gegenstand. If Sie den Besitzer suchen, verlieren Sie bitte nicht auch noch my time.","english":"That is not my lost object. If you are looking for its owner, please do not lose my time as well."},{"id":"stadt-joachim-fundsache-04","text":"Die responsibility liegt hier irgendwo. If Sie sie finden, geben Sie sie bitte not bei mir ab.","english":"The responsibility is lying around here somewhere. If you find it, please do not hand it in to me."}]},"city-ute-ruhe":{"voiceId":"stadt-ute-ruhe","germany":[{"id":"stadt-ute-ruhe-01","text":"Könnten Sie einen Schritt leiser treten? Man hört schon von hier, dass Sie noch etwas vorhaben.","english":"Could you take a quieter step? I can already hear from here that you still have plans."},{"id":"stadt-ute-ruhe-02","text":"Lassen Sie die Lücke bitte frei. Ich brauche nicht viel Platz, nur genau den, den gerade keiner benutzt.","english":"Please leave that gap clear. I do not need much space, just precisely the space that nobody is using right now."}],"berlin":[{"id":"stadt-ute-ruhe-03","text":"Could Sie einen Schritt more quietly treten? Man hört schon von hier, dass Sie still have plans.","english":"Could you take a quieter step? I can already hear from here that you still have plans."},{"id":"stadt-ute-ruhe-04","text":"Please lassen Sie die Lücke clear. Ich brauche nicht much space, nur genau den, den gerade nobody uses.","english":"Please leave that gap clear. I do not need much space, just precisely the space that nobody is using right now."}]},"city-norbert-faxrolle":{"voiceId":"stadt-norbert-faxrolle","germany":[{"id":"stadt-norbert-faxrolle-01","text":"Ich habe es gefaxt. Dass das Gerät seit Dienstag kein Papier hat, ändert nichts daran, dass ich meinen Teil versucht habe.","english":"I faxed it. The machine having no paper since Tuesday does not change the fact that I attempted my part."},{"id":"stadt-norbert-faxrolle-02","text":"Das Original ist auf dem Fax verschwunden. Nehmen Sie die Kopie, da sieht man wenigstens noch, was ursprünglich gefehlt hat.","english":"The original disappeared on the fax. Take the copy; at least it still shows what was missing in the first place."}],"berlin":[{"id":"stadt-norbert-faxrolle-03","text":"I have gefaxt it. Dass das Gerät seit Tuesday kein Papier hat, ändert nichts daran, dass ich my part versucht habe.","english":"I faxed it. The machine having no paper since Tuesday does not change the fact that I attempted my part."},{"id":"stadt-norbert-faxrolle-04","text":"The Original ist auf dem Fax verschwunden. Take die Kopie, da sieht man wenigstens noch, what originally was missing.","english":"The original disappeared on the fax. Take the copy; at least it still shows what was missing in the first place."}]},"city-edeltraud-trennung":{"voiceId":"stadt-edeltraud-trennung","germany":[{"id":"stadt-edeltraud-trennung-01","text":"Die Terminfrage und die Baustellenfrage bitte getrennt. Sonst erzählen Sie dem Kalender, warum der Bauzaun im Weg steht.","english":"Please keep the appointment question separate from the construction question. Otherwise you will tell the calendar why the construction fence is in the way."},{"id":"stadt-edeltraud-trennung-02","text":"Sortieren Sie erst, was Sie wissen wollen, und dann, wer es wissen soll. Im Moment haben Sie beides bei mir abgelegt.","english":"First sort out what you want to know, and then who is supposed to know it. At the moment, you have filed both with me."}],"berlin":[{"id":"stadt-edeltraud-trennung-03","text":"Die appointment question und die Baustellenfrage bitte separate. Otherwise erzählen Sie dem Kalender, why der Bauzaun im Weg steht.","english":"Please keep the appointment question separate from the construction question. Otherwise you will tell the calendar why the construction fence is in the way."},{"id":"stadt-edeltraud-trennung-04","text":"First sortieren Sie, what Sie wissen wollen, und dann, who es wissen soll. Right now haben Sie beides bei mir abgelegt.","english":"First sort out what you want to know, and then who is supposed to know it. At the moment, you have filed both with me."}]}});
function productionClip(clip){const exception=productionExceptions[clip.id],binding=exception?.voiceId===clip.voiceId?exception:productionVoices[clip.voiceId];if(!binding)return !clip.fixedProduction;if(clip.profileId!==binding.profileId)return false;const expected={renderer:binding.renderer,modelRevision:binding.modelRevision,referenceSha256:clip.referenceHashKind==="uploaded-original"?binding.originalSha256:binding.referenceSha256,referenceOriginalSha256:binding.originalSha256,processing:binding.processing??null};return Object.entries(expected).every(([key,value])=>(!clip.fixedProduction&&clip[key]===undefined)||clip[key]===value)}
